import sys
from itertools import product

def solve():
    data = sys.stdin.read().split()
    n = int(data[0])
    D = list(map(int, data[1:1+n]))
    L1, C1, K1 = map(int, data[1+n:1+n+3])
    L2, C2, K2 = map(int, data[1+n+3:1+n+6])

    # Precompute max coverage for combinations of sensors within limits
    # For each count of sensor1 (0..K1), compute max coverage and cost
    options = []
    for s1 in range(K1 + 1):
        rem_len = sum(D)
        if s1 * L1 >= rem_len:
            options.append((s1 * C1, s1, 0))
            continue
        rem_after_s1 = rem_len - s1 * L1
        min_s2 = (rem_after_s1 + L2 - 1) // L2
        if min_s2 <= K2:
            options.append((s1 * C1 + min_s2 * C2, s1, min_s2))

    # But we need to assign sensors to individual sections
    # Try all valid distributions of sensors across sections
    min_cost = float('inf')

    # For each section, try different numbers of sensor1 and sensor2
    # We'll iterate over possible total counts of sensors used
    for total_s1 in range(K1 + 1):
        for total_s2 in range(K2 + 1):
            # Check if this combination can cover all sections
            # For each section, check if it can be covered by some split of sensors
            def can_cover_section(d, s1_used, s2_used):
                # Try different ways to assign s1 and s2 sensors to this section
                for a in range(s1_used + 1):
                    for b in range(s2_used + 1):
                        if a * L1 + b * L2 >= d:
                            return True
                return False

            # Try to distribute total_s1 and total_s2 across sections
            # Use recursion/backtracking
            def backtrack(sec_idx, rem_s1, rem_s2):
                if sec_idx == n:
                    return True
                d = D[sec_idx]
                for a in range(rem_s1 + 1):
                    for b in range(rem_s2 + 1):
                        if a * L1 + b * L2 >= d:
                            if backtrack(sec_idx + 1, rem_s1 - a, rem_s2 - b):
                                return True
                return False

            if backtrack(0, total_s1, total_s2):
                min_cost = min(min_cost, total_s1 * C1 + total_s2 * C2)

    print(-1 if min_cost == float('inf') else min_cost)

