def countKeyChanges(s):
    if len(s) <= 1:
        return 0

    changes = 0
    prev_key = s[0].lower()

    for i in range(1, len(s)):
        current_key = s[i].lower()
        if current_key != prev_key:
            changes += 1
        prev_key = current_key

    return changes
```

