def minOperations(word: str) -> int:
    n = len(word)
    if n == 0:
        return 0
    INF = float('inf')
    dp = [[INF] * 26 for _ in range(n)]
    for j in range(26):
        cost = 0 if ord(word[0]) - ord('a') == j else 1
        dp[0][j] = cost
    for i in range(1, n):
        for prev in range(26):
            if dp[i - 1][prev] == INF:
                continue
            for curr in range(26):
                if abs(curr - prev) >= 2:
                    cost = 0 if ord(word[i]) - ord('a') == curr else 1
                    dp[i][curr] = min(dp[i][curr], dp[i - 1][prev] + cost)
    return min(dp[n - 1])
