def numberOfWays(n: int, x: int) -> int:
    MOD = 10**9 + 7
    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        num_power = i ** x
        if num_power > n:
            break
        for j in range(n, num_power - 1, -1):
            dp[j] = (dp[j] + dp[j - num_power]) % MOD

    return dp[n]
