def solve(wordsContainer, wordsQuery):
    def get_suffix(s, k):
        return s[-k:] if k <= len(s) else ""

    n = len(wordsContainer)
    ans = []

    # Precompute reversed strings for faster suffix matching
    rev_container = [s[::-1] for s in wordsContainer]

    for query in wordsQuery:
        rev_query = query[::-1]
        max_suffix_len = 0
        best_idx = 0

        # Try all possible suffix lengths from longest to shortest
        for i in range(n):
            container_word = rev_container[i]
            min_len = min(len(container_word), len(rev_query))
            common_len = 0

            # Check how many characters match from the start (which is suffix in original)
            for j in range(min_len):
                if container_word[j] == rev_query[j]:
                    common_len += 1
                else:
                    break

            if common_len > max_suffix_len:
                max_suffix_len = common_len
                best_idx = i
            elif common_len == max_suffix_len and common_len > 0:
                # Tie-breaking: smallest length first, then earliest occurrence
                if len(wordsContainer[i]) < len(wordsContainer[best_idx]):
                    best_idx = i
                # If same length, keep the one with smaller index (earlier occurrence)

        # If no suffix matched, we need to choose based on shortest length and earliest occurrence
        if max_suffix_len == 0:
            best_idx = 0
            for i in range(1, n):
                if len(wordsContainer[i]) < len(wordsContainer[best_idx]):
                    best_idx = i

        ans.append(best_idx)

    return ans
