    spf = [0] * (MAX + 1)
    for i in range(2, MAX + 1):
        spf[i] = i
    for i in range(2, int(MAX ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, MAX + 1, i):
                if spf[j] == j:
                    spf[j] = i

    def get_kernel(x, spf):
        kernel = 1
        while x > 1:
            p = spf[x]
            cnt = 0
            while x % p == 0:
                x //= p
                cnt += 1
            if cnt % 2 == 1:
                kernel *= p
        return kernel

    cnt = Counter()
    Z = 0
    for a in A:
        if a == 0:
            Z += 1
        else:
            k = get_kernel(a, spf)
            cnt[k] += 1

    ans = Z * (N - Z) + (Z * (Z - 1)) // 2
    for c in cnt.values():
        ans += c * (c - 1) // 2
    print(ans)

