                return cur == target
            key = (pos, cur)
            if key in memo:
                return memo[key]
            res = False
            num = 0
            for j in range(pos, m):
                num = num * 10 + int(s[j])
                new_cur = cur + num
                if new_cur > target:
                    break
                if dfs(j + 1, new_cur):
