        return True
    MAXN = 100000
    spf = list(range(MAXN + 1))
    spf[0] = spf[1] = 0
    for i in range(2, int(MAXN ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, MAXN + 1, i):
                if spf[j] == j:
                    spf[j] = i

    primes_to_indices = defaultdict(list)
    for i in range(n):
        x = nums[i]
        if x == 1:
            continue
        primes = set()
        tx = x
        while tx > 1:
            p = spf[tx]
            primes.add(p)
            while tx % p == 0:
                tx //= p
        for p in primes:
            primes_to_indices[p].append(i)

    class UnionFind:
        def __init__(self, n):
            self.p = list(range(n))
            self.rank = [0] * n

        def find(self, x):
            root = x
            while self.p[root] != root:
                root = self.p[root]
            while x != root:
                nxt = self.p[x]
                self.p[x] = root
                x = nxt
            return root

        def union(self, x, y):
            px = self.find(x)
            py = self.find(y)
            if px == py:
                return
            if self.rank[px] < self.rank[py]:
                self.p[px] = py
            elif self.rank[px] > self.rank[py]:
                self.p[py] = px
            else:
                self.p[py] = px
                self.rank[px] += 1

    uf = UnionFind(n)
    for indices in primes_to_indices.values():
        if len(indices) < 2:
            continue
        first = indices[0]
        for idx in indices[1:]:
            uf.union(first, idx)

    root0 = uf.find(0)
    for i in range(1, n):
        if uf.find(i) != root0:
            return False
    return True
