def solution(s: str, k: int) -> str:
    n = len(s)
    orig = [ord(c) - ord('a') for c in s]
    t = [''] * n
    rem = k
    for i in range(n):
        for x in range(26):
            d = min(abs(orig[i] - x), 26 - abs(orig[i] - x))
            if d <= rem:
                t[i] = chr(ord('a') + x)
                rem -= d
                break
    return ''.join(t)
