def maxJumps(nums, target):
    n = len(nums)
    dp = [-1] * n
    dp[0] = 0
    for i in range(1, n):
        max_prev = -1
        for j in range(i):
            if abs(nums[i] - nums[j]) <= target and dp[j] != -1:
                max_prev = max(max_prev, dp[j])
        if max_prev != -1:
            dp[i] = max_prev + 1
    return dp[n - 1]
