def longest_subsequence(nums, target):
    n = len(nums)
    dp = {0: 0}  # {sum: length of subsequence}

    for num in nums:
        # Update the dp in reverse order to avoid using the same num multiple times
        for s in list(dp.keys())[::-1]:
            new_sum = s + num
            new_length = dp[s] + 1

            if new_sum not in dp or new_length > dp[new_sum]:
                dp[new_sum] = new_length

    return dp.get(target, -1)
```

